"""DEV Command Centre — one page, one address, survives a restart.

ARMS layer bonus / gap 5. Serves a single read-only status page at
http://127.0.0.1:7373 that answers one question: is anything broken?

Design notes that matter:

* **Standard library only.** No venv, no pip, nothing to upgrade. Python 3.14
  on this machine is PEP 668-managed, so a dependency would mean a venv to
  maintain forever for a read-only local page. Not worth it.
* **Rendered fresh on every request.** Nothing is cached and nothing is
  regenerated on a timer, so the page can never be stale — staleness is the
  failure mode that makes a dashboard get ignored.
* **Bound to 127.0.0.1 only.** Not reachable from the network, which is why it
  needs no auth. Do not change the bind address without adding one.
* **Read-only.** It never writes, never runs a skill, never touches the network.
  A stray browser tab cannot trigger anything.
* **Live launchctl state is the truth.** KeystoneOS's run-ledger.json has
  misreported job state before, so it is shown as supporting detail only and is
  never allowed to claim a job succeeded.
* **Every source is optional.** A missing or malformed source renders as
  "unknown" with the reason. The page must never 500 and never go blank —
  a command centre that crashes when one input is missing is worse than none.
"""
import html
import json
import os
import re
import subprocess
import time
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

HOME = Path.home()
DEV = HOME / 'DEV'
PORT = 7373

BACKUP_LOG = HOME / '.claude/scripts/logs/daily-backup.log'
EXTRACT_LOG = DEV / 'graphify-out/daily_extract.log'
GEM_DONE = DEV / 'graphify-out/.graphify_gemini_done.txt'
DETECT = DEV / 'graphify-out/.graphify_detect.json'
PORTFOLIO = DEV / 'project-triage/portfolio.json'
ERRORS = HOME / '.claude/global-memory/transcripts/.errors.log'
LEDGER = DEV / 'KeystoneOS/outputs/run-ledger.json'

OK, WARN, BAD, UNKNOWN = 'ok', 'warn', 'bad', 'unknown'


def _age(p: Path) -> str:
    """Human age of a file's mtime, or '' when it does not exist."""
    try:
        secs = time.time() - p.stat().st_mtime
    except OSError:
        return ''
    for limit, div, unit in ((90, 1, 's'), (5400, 60, 'min'), (172800, 3600, 'h')):
        if secs < limit:
            return f'{int(secs / div)}{unit} ago'
    return f'{int(secs / 86400)}d ago'


def _tail(p: Path, n: int = 400) -> list[str]:
    try:
        return p.read_text(errors='replace').splitlines()[-n:]
    except OSError:
        return []


# --------------------------------------------------------------------------
# Sources. Each returns (state, headline, list_of_detail_lines) and NEVER
# raises — a broken input degrades to UNKNOWN rather than taking the page down.
# --------------------------------------------------------------------------

def src_agents():
    try:
        out = subprocess.run(['launchctl', 'list'], capture_output=True,
                             text=True, timeout=10).stdout
    except Exception as e:                                    # noqa: BLE001
        return UNKNOWN, 'cannot read launchctl', [str(e)[:120]]

    rows = []
    for line in out.splitlines():
        parts = line.split('\t')
        if len(parts) < 3 or not parts[2].startswith('com.keystone.'):
            continue
        pid, status, label = parts[0], parts[1], parts[2]
        name = label.replace('com.keystone.', '')
        try:
            code = int(status)
        except ValueError:
            code = -1
        rows.append((name, code, pid))
    if not rows:
        return UNKNOWN, 'no com.keystone.* agents registered', []

    rows.sort()
    bad = [r for r in rows if r[1] != 0]
    detail = [f'{n:<16} exit {c}' + ('  (running)' if p not in ('-', '0') else '')
              for n, c, p in rows]
    if not bad:
        return OK, f'{len(rows)} agents, all clean', detail
    # A nonzero code is the LAST run's result and can be stale after a fix, so
    # this is a warning to go look, never a claim that something is broken now.
    names = ', '.join(n for n, _, _ in bad)
    return WARN, f'{len(bad)} of {len(rows)} reporting nonzero: {names}', detail


def src_backup():
    lines = _tail(BACKUP_LOG)
    if not lines:
        return UNKNOWN, 'no backup log found', [str(BACKUP_LOG)]
    ends = [l for l in lines if 'daily-backup end:' in l]
    if not ends:
        return UNKNOWN, 'log has no completed run', [lines[-1][:160]]
    last = ends[-1]
    state = OK if ' OK (' in last else BAD
    return state, last.strip()[:160], [f'log {_age(BACKUP_LOG)}']


def src_graph():
    done = total = None
    try:
        done = len([l for l in GEM_DONE.read_text().splitlines() if l.strip()])
    except OSError:
        pass
    try:
        d = json.loads(DETECT.read_text())
        files = d.get('files', {})
        total = sum(len(files.get(c, [])) for c in ('document', 'paper', 'image'))
        total += len([f for f in files.get('code', [])
                      if f.lower().endswith(('.r', '.rmd'))])
    except Exception:                                         # noqa: BLE001
        pass
    if done is None or not total:
        return UNKNOWN, 'graph progress unreadable', []

    left = max(0, total - done)
    detail = [f'{done} of {total} files extracted', f'last pass {_age(EXTRACT_LOG)}']
    tail = _tail(EXTRACT_LOG, 60)
    for line in reversed(tail):
        if 'remaining after' in line:
            detail.append(line.strip()[:120])
            break
    if left == 0:
        return OK, 'corpus complete — the daily extract job can be removed', detail
    # ~120 free requests/day across the model buckets works out near 90 files.
    return WARN, f'{left} files left (~{max(1, round(left / 90))} more mornings)', detail


def src_errors():
    if not ERRORS.exists():
        return UNKNOWN, 'error log missing', [str(ERRORS)]
    lines = [l for l in _tail(ERRORS, 40) if l.strip()]
    if not lines:
        return OK, 'no logged failures', []
    return BAD, f'{len(lines)} logged failure(s)', [l[:160] for l in lines[-5:]]


def src_projects():
    try:
        d = json.loads(PORTFOLIO.read_text())
    except Exception as e:                                    # noqa: BLE001
        return UNKNOWN, 'portfolio unreadable', [str(e)[:120]]
    projects = d.get('projects') or []
    active = [p for p in projects if str(p.get('status', '')).lower() == 'active']
    active.sort(key=lambda p: p.get('rank') or 999)
    detail = [f"{(p.get('rank') or '?'):>3}  {p.get('name', '?')}"
              f"  [{p.get('stage', '?')}]" for p in active[:12]]
    inbox = len(d.get('inbox') or [])
    head = f'{len(active)} active of {len(projects)}'
    if inbox:
        head += f' · {inbox} in inbox'
    return OK, head, detail


def src_ledger():
    """Supporting detail only. Never used to assert that a job succeeded."""
    try:
        d = json.loads(LEDGER.read_text())
    except Exception:                                         # noqa: BLE001
        return UNKNOWN, 'no run ledger', []
    jobs = d.get('jobs') or {}
    rows = []
    for name, runs in jobs.items():
        if not runs:
            continue
        last = runs[-1]
        rows.append(f"{name:<18} {last.get('date', '?')}  {last.get('status', '?')}")
    rows.sort()
    return UNKNOWN, f'{len(rows)} job(s) recorded — not authoritative', rows[:10]


LINKS = [
    ('Knowledge graph', DEV / 'graphify-out/graph.html'),
    ('Project board', DEV / 'project-triage/board.html'),
    ('Project triage', DEV / 'project-triage/dashboard.html'),
    ('VALD report', DEV / 'ValdReport/index.html'),
    ('S2 evaluation', DEV / 'S2_Evaluation/report.html'),
    ('Coach report A', DEV / 'Football/CoachReport_Prototypes/pdf/prototype_a_analytics.pdf'),
    ('Coach report B', DEV / 'Football/CoachReport_Prototypes/pdf/prototype_b_demand.pdf'),
    ('Research repo', DEV / 'SportScienceResearchRepo/index.html'),
]

CSS = """
:root{--bg:#fbfaf8;--fg:#1a1a1a;--dim:#6b6b6b;--line:#e3e0da;--card:#fff;
