def _age(p: Path) -> str:
    """Human age of a file's mtime, or '' when it does not exist."""
    try:
        secs = time.time() - p.stat().st_mtime
    except OSError:
        return ''
    for limit, div, unit in ((90, 1, 's'), (5400, 60, 'min'), (172800, 3600, 'h')):
